}

package com.rustyledger;

import java.math.BigDecimal;
import java.util.HashMap;
import java.util.Map;

public class AccountRegistry {
    private final Map<String, Account> accounts = new HashMap<>();

    public void openAccount(String id, String tier, String currency, BigDecimal balance) {
        if (accounts.containsKey(id)) {
            throw new IllegalStateException("ACCOUNT EXISTS: " + id);
        }
        accounts.put(id, new Account(tier, currency, balance));
    }

    public Account getAccount(String id) {
        return accounts.get(id);
    }

    public boolean contains(String id) {
        return accounts.containsKey(id);
    }
}

package com.rustyledger;

import java.util.ArrayList;
import java.util.List;

public class AuditLogger {
    private final List<String> audit = new ArrayList<>();
    private int auditSeq = 0;

    public void record(String verb, String date, String outcome) {
        auditSeq++;
        audit.add(String.format("%03d  %s %s %s", auditSeq, verb, date, outcome));
    }

    public List<String> getLog() {
        return new ArrayList<>(audit);
    }
}

package com.rustyledger;

import java.math.BigDecimal;
import java.math.RoundingMode;

public class CurrencyConverter {
    private BigDecimal rate(String currency) {
        if (currency.equals("EUR")) return new BigDecimal("4.30");
        if (currency.equals("USD")) return new BigDecimal("4.00");
        return new BigDecimal("1.00");
    }

    public BigDecimal convert(BigDecimal amount, String from, String to, String tier) {
        BigDecimal inPln = amount.multiply(rate(from)).setScale(4, RoundingMode.HALF_UP);
        BigDecimal result = inPln.divide(rate(to), 4, RoundingMode.HALF_UP);
        if (!"STAFF".equals(tier)) {
            result = result.multiply(new BigDecimal("0.985"));
        }
        return result.setScale(2, RoundingMode.HALF_DOWN);
    }
}

package com.rustyledger;

import java.math.BigDecimal;
import java.math.RoundingMode;

public class FeeCalculator {
    public BigDecimal calculateTransferFee(String tier, BigDecimal amount) {
        if ("STANDARD".equals(tier)) {
            BigDecimal fee = amount.multiply(new BigDecimal("0.005")).setScale(2, RoundingMode.HALF_UP);
            return fee.max(new BigDecimal("0.20"));
        } else if ("PREMIUM".equals(tier)) {
            BigDecimal fee = amount.multiply(new BigDecimal("0.0025")).setScale(2, RoundingMode.HALF_UP);
            return fee.max(new BigDecimal("0.10")).min(new BigDecimal("5.00"));
        }
        return BigDecimal.ZERO;
    }

    public BigDecimal calculateWithdrawFee(String tier) {
        return "STANDARD".equals(tier) ? new BigDecimal("1.00") : BigDecimal.ZERO;
    }
}

package com.rustyledger;

import java.math.BigDecimal;
import java.util.List;

public class LedgerImpl implements Ledger {
    private final AccountRegistry accounts = new AccountRegistry();
    private final TransactionRegistry transactions = new TransactionRegistry();
    private final AuditLogger audit = new AuditLogger();
    private final StatisticsTracker stats = new StatisticsTracker();
    private final CurrencyConverter converter = new CurrencyConverter();
    private final FeeCalculator fees = new FeeCalculator();
    private final UsageTracker usage = new UsageTracker();

    public void openAccount(String id, String tier, String currency, String openingBalance) {
        if (id == null || id.trim().isEmpty() || id.contains("|")) {
            throw new IllegalArgumentException("INVALID ACCOUNT ID");
        }
        if (!"STANDARD".equals(tier) && !"PREMIUM".equals(tier) && !"STAFF".equals(tier)) {
            throw new IllegalArgumentException("INVALID TIER: " + tier);
        }
        if (!"PLN".equals(currency) && !"EUR".equals(currency) && !"USD".equals(currency)) {
            throw new IllegalArgumentException("INVALID CURRENCY: " + currency);
        }
        if (openingBalance == null || !openingBalance.matches("\\d+(\\.\\d{1,2})?")) {
            throw new IllegalArgumentException("INVALID AMOUNT: " + openingBalance);
        }
        accounts.openAccount(id, tier, currency, new BigDecimal(openingBalance).setScale(2));
    }

    public String balance(String id) {
        Account a = accounts.getAccount(id);
        if (a == null) throw new IllegalArgumentException("UNKNOWN ACCOUNT: " + id);
        return a.getBalance() + " " + a.getCurrency();
    }

    public List<String> auditLog() { return audit.getLog(); }

    public String dailyReport(String date) { return stats.getReport(date); }

    public String submit(String line) {
        if (line == null || line.trim().isEmpty()) {
            return reject("???", null, "BAD_INSTRUCTION", "empty instruction");
        }
        String[] f = line.split("\\|", -1);
        String verb = f[0];
        int want = getWant(verb);
        if (want == -1) return reject("???", null, "BAD_INSTRUCTION", "unknown verb " + verb);
        if (f.length != want) return reject(verb, null, "BAD_INSTRUCTION", verb + " needs " + want + " fields");
        String date = f[1];
        if (!date.matches("\\d{4}-\\d{2}-\\d{2}")) return reject(verb, null, "BAD_DATE", date);
        if (verb.equals("REVERSE")) return doReverse(date, f[2]);
        String amtTxt = verb.equals("TRANSFER") ? f[4] : f[3];
        if (!amtTxt.matches("\\d+(\\.\\d{1,2})?")) return reject(verb, date, "BAD_AMOUNT", amtTxt);
        BigDecimal amt = new BigDecimal(amtTxt).setScale(2);
        if (amt.signum() <= 0) return reject(verb, date, "BAD_AMOUNT", amtTxt);
        if (verb.equals("TRANSFER")) return doTransfer(date, f[2], f[3], amt, f[5]);
        if (verb.equals("WITHDRAW")) return doWithdraw(date, f[2], amt);
        return doDeposit(date, f[2], amt);
    }

    private int getWant(String verb) {
        if (verb.equals("TRANSFER")) return 6;
        if (verb.equals("WITHDRAW") || verb.equals("DEPOSIT")) return 4;
        if (verb.equals("REVERSE")) return 3;
        return -1;
    }

    private String doTransfer(String date, String fromId, String toId, BigDecimal amt, String cur) {
        Account from = accounts.getAccount(fromId);
        if (from == null) return reject("TRANSFER", date, "UNKNOWN_ACCOUNT", fromId);
        Account to = accounts.getAccount(toId);
        if (to == null) return reject("TRANSFER", date, "UNKNOWN_ACCOUNT", toId);
        if (fromId.equals(toId)) return reject("TRANSFER", date, "SAME_ACCOUNT", "cannot transfer to the same account");
        if (!from.getCurrency().equals(cur)) return reject("TRANSFER", date, "CURRENCY_MISMATCH", fromId + " holds " + from.getCurrency());
        BigDecimal fee = fees.calculateTransferFee(from.getTier(), amt);
        String rej = checkLimitAndFunds(date, fromId, from, amt, fee);
        if (rej != null) return reject("TRANSFER", date, rej.split(": ")[1], rej.split(": ")[1]);
        // Note: the original logic for error reporting is slightly specific. 
        // Let's fix the rejection return to match exactly.
        if (rej != null) {
            String[] parts = rej.split(": ", 2);
            return reject("TRANSFER", date, parts[0], parts[1]);
        }
        BigDecimal cred = from.getCurrency().equals(to.getCurrency()) ? amt : converter.convert(amt, from.getCurrency(), to.getCurrency(), from.getTier());
        String txId = transactions.nextId();
        from.setBalance(from.getBalance().subtract(amt.add(fee)));
        to.setBalance(to.getBalance().add(cred));
        usage.add(fromId, date, amt);
        transactions.put(txId, new TransactionRecord("TRANSFER", date, fromId, toId, amt, from.getCurrency(), fee, cred, false));
        stats.addFee(date, from.getCurrency(), fee);
        return accept("TRANSFER", date, txId, "fee=" + fee + " " + from.getCurrency());
    }

    private String doWithdraw(String date, String id, BigDecimal amt) {
        Account a = accounts.getAccount(id);
        if (a == null) return reject("WITHDRAW", date, "UNKNOWN_ACCOUNT", id);
        BigDecimal fee = fees.calculateWithdrawFee(a.getTier());
        String rej = checkLimitAndFunds(date, id, a, amt, fee);
        if (rej != null) {
            String[] parts = rej.split(": ", 2);
            return reject("WITHDRAW", date, parts[0], parts[1]);
        }
        String txId = transactions.nextId();
        a.setBalance(a.getBalance().subtract(amt.add(fee)));
        usage.add(id, date, amt);
        transactions.put(txId, new TransactionRecord("WITHDRAW", date, id, "", amt, a.getCurrency(), fee, amt, false));
        stats.addFee(date, a.getCurrency(), fee);
        return accept("WITHDRAW", date, txId, "fee=" + fee + " " + a.getCurrency());
    }

    private String doDeposit(String date, String id, BigDecimal amt) {
        Account a = accounts.getAccount(id);
        if (a == null) return reject("DEPOSIT", date, "UNKNOWN_ACCOUNT", id);
        String txId = transactions.nextId();
        a.setBalance(a.getBalance().add(amt));
        transactions.put(txId, new TransactionRecord("DEPOSIT", date, id, "", amt, a.getCurrency(), BigDecimal.ZERO, amt, false));
        return accept("DEPOSIT", date, txId, "fee=0.00 " + a.getCurrency());
    }

    private String doReverse(String date, String txId) {
        TransactionRecord tx = transactions.get(txId);
        if (tx == null) return reject("REVERSE", date, "UNKNOWN_TX", txId);
        if (!"TRANSFER".equals(tx.verb)) return reject("REVERSE", date, "NOT_REVERSIBLE", txId + " is a " + tx.verb);
        if (tx.reversed) return reject("REVERSE", date, "ALREADY_REVERSED", txId);
        if (!tx.date.equals(date)) return reject("REVERSE", date, "REVERSAL_WINDOW", txId + " was made on " + tx.date);
        Account from = accounts.getAccount(tx.fromId);
        Account to = accounts.getAccount(tx.toId);
        BigDecimal fee = tx.fee;
        to.setBalance(to.getBalance().subtract(tx.credited));
        BigDecimal back = tx.amount;
        if ("PREMIUM".equals(from.getTier())) {
            back = back.add(fee);
            if (fee.signum() != 0) stats.addFee(date, from.getCurrency(), fee.negate());
        }
        from.setBalance(from.getBalance().add(back));
        tx.reversed = true;
        String newId = transactions.nextId();
        transactions.put(newId, new TransactionRecord("REVERSE", date, tx.fromId, tx.toId, tx.amount, tx.currency, BigDecimal.ZERO, tx.credited, true));
        return accept("REVERSE", date, newId, "reversed " + txId);
    }

    private String checkLimitAndFunds(String date, String id, Account a, BigDecimal amt, BigDecimal fee) {
        BigDecimal limit = "STANDARD".equals(a.getTier()) ? new BigDecimal("5000.00") :
                           "PREMIUM".equals(a.getTier()) ? new BigDecimal("20000.00") : new BigDecimal("50000.00");
        BigDecimal overdraft = "PREMIUM".equals(a.getTier()) ? new BigDecimal("500.00") : BigDecimal.ZERO;
        if (usage.getUsed(id, date).add(amt).compareTo(limit) > 0) {
            return "LIMIT_EXCEEDED: daily limit " + limit + " for " + a.getTier();
        }
        BigDecimal needed = amt.add(fee);
        if (a.getBalance().subtract(needed).compareTo(overdraft.negate()) < 0) {
            return "INSUFFICIENT_FUNDS: balance " + a.getBalance() + " " + a.getCurrency() + ", needed " + needed + " " + a.getCurrency();
        }
        return null;
    }

    private String accept(String verb, String date, String txId, String extra) {
        stats.count(date, 0);
        audit.record(verb, date, "OK " + txId);
        return "OK " + txId + " " + extra;
    }

    private String reject(String verb, String date, String code, String msg) {
        if (date != null) stats.count(date, 1);
        audit.record(verb, date == null ? "????-??-??" : date, "REJECTED " + code);
        return "REJECTED " + code + ": " + msg;
    }
}

package com.rustyledger;

import java.math.BigDecimal;

public class TransactionRecord {
    public final String verb;
    public final String date;
    public final String fromId;
    public final String toId;
    public final BigDecimal amount;
    public final String currency;
    public final BigDecimal fee;
    public final BigDecimal credited;
    public boolean reversed;

    public TransactionRecord(String verb, String date, String fromId, String toId, BigDecimal amount,
                             String currency, BigDecimal fee, BigDecimal credited, boolean reversed) {
        this.verb = verb;
        this.date = date;
        this.fromId = fromId;
        this.toId = toId;
        this.amount = amount;
        this.currency = currency;
        this.fee = fee;
        this.credited = credited;
        this.reversed = reversed;
    }
}

package com.rustyledger;

import java.util.HashMap;
import java.util.Map;

public class TransactionRegistry {
    private final Map<String, TransactionRecord> txs = new HashMap<>();
    private int txSeq = 0;

    public String nextId() {
        txSeq++;
        return String.format("TX-%06d", txSeq);
    }

    public void put(String id, TransactionRecord record) { txs.put(id, record); }
    public TransactionRecord get(String id) { return txs.get(id); }
}

package com.rustyledger;

import java.math.BigDecimal;
import java.util.HashMap;
import java.util.Map;
import java.util.TreeMap;

public class StatisticsTracker {
    private final Map<String, int[]> counts = new HashMap<>();
    private final Map<String, Map<String, BigDecimal>> fees = new HashMap<>();

    public void count(String date, int slot) {
        int[] c = counts.computeIfAbsent(date, k -> new int[2]);
        c[slot]++;
    }

    public void addFee(String date, String cur, BigDecimal delta) {
        if (delta.signum() == 0) return;
        Map<String, BigDecimal> m = fees.computeIfAbsent(date, k -> new TreeMap<>());
        m.put(cur, m.getOrDefault(cur, BigDecimal.ZERO).add(delta));
    }

    public String getReport(String date) {
        int[] c = counts.get(date);
        int ok = c == null ? 0 : c[0];
        int rej = c == null ? 0 : c[1];
        Map<String, BigDecimal> f = fees.get(date);
        String feeText = "none";
        if (f != null && !f.isEmpty()) {
            StringBuilder sb = new StringBuilder();
            for (Map.Entry<String, BigDecimal> e : f.entrySet()) {
                if (sb.length() > 0) sb.append(", ");
                sb.append(e.getValue()).append(" ").append(e.getKey());
            }
            feeText = sb.toString();
        }
        return "REPORT " + date + "\nok: " + ok + "\nrejected: " + rej + "\nfees: " + feeText;
    }
}

package com.rustyledger;

import java.math.BigDecimal;
import java.util.HashMap;
import java.util.Map;

public class UsageTracker {
    private final Map<String, BigDecimal> used = new HashMap<>();

    public void add(String id, String date, BigDecimal amt) {
        String key = id + "|" + date;
        used.put(key, used.getOrDefault(key, BigDecimal.ZERO).add(amt));
    }

    public BigDecimal getUsed(String id, String date) {
        return used.getOrDefault(id + "|" + date, BigDecimal.ZERO);
    }
}

